{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { randomUUID } from 'node:crypto';
import { extname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('.', import.meta.url));
const publicDirectory = join(root, 'public');
const database = new DatabaseSync(process.env.DB_PATH || join(root, 'workboard.sqlite'));
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    created_at INTEGER NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    created_at INTEGER NOT NULL
  )
`);

const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');
}

const listProjects = database.prepare(`
  SELECT p.id, p.name, p.archived, COUNT(t.id) AS totalCount,
    SUM(CASE WHEN t.completed = 1 THEN 1 ELSE 0 END) AS completedCount
  FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
  WHERE p.archived = ? GROUP BY p.id ORDER BY p.created_at, p.rowid
`);
const getProject = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
const updateProjectArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0');
const insertProject = database.prepare('INSERT INTO projects (id, name, created_at) VALUES (?, ?, ?)');
const listTasks = database.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY created_at, rowid');
const insertTask = database.prepare('INSERT INTO tasks (id, project_id, title, completed, created_at) VALUES (?, ?, ?, 0, ?)');
const getTask = database.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE id = ? AND project_id = ?');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

async function readJson(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  try {
    return JSON.parse(body);
  } catch {
    return null;
  }
}

function sendJson(response, statusCode, value) {
  response.writeHead(statusCode, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');
  if (url.pathname === '/health' && request.method === 'GET') {
    sendJson(response, 200, { status: 'ok' });
    return;
  }

  if (url.pathname === '/api/projects' && request.method === 'GET') {
    sendJson(response, 200, listProjects.all(url.searchParams.get('filter') === 'Archived' ? 1 : 0));
    return;
  }

  if (url.pathname === '/api/projects' && request.method === 'POST') {
    const body = await readJson(request);
    const name = typeof body?.name === 'string' ? body.name.trim() : '';
    if (!name) {
      sendJson(response, 400, { error: 'Project name is required' });
      return;
    }
    const project = { id: randomUUID(), name, archived: 0 };
    insertProject.run(project.id, project.name, Date.now());
    sendJson(response, 201, project);
    return;
  }

  const archiveMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/archive$/);
  if (archiveMatch && request.method === 'PATCH') {
    const projectId = decodeURIComponent(archiveMatch[1]);
    const project = getProject.get(projectId);
    if (!project) {
      sendJson(response, 404, { error: 'Project not found' });
      return;
    }
    const body = await readJson(request);
    if (typeof body?.archived !== 'boolean') {
      sendJson(response, 400, { error: 'Project archive state must be a boolean' });
      return;
    }
    updateProjectArchive.run(body.archived ? 1 : 0, projectId);
    sendJson(response, 200, { ...project, archived: body.archived ? 1 : 0 });
    return;
  }

  const projectMatch = url.pathname.match(/^\/api\/projects\/([^/]+)$/);
  if (projectMatch && ['GET', 'PATCH'].includes(request.method)) {
    const projectId = decodeURIComponent(projectMatch[1]);
    const project = getProject.get(projectId);
    if (!project) {
      sendJson(response, 404, { error: 'Project not found' });
      return;
    }
    if (request.method === 'PATCH') {
      const body = await readJson(request);
      const name = typeof body?.name === 'string' ? body.name.trim() : '';
      if (!name) {
        sendJson(response, 400, { error: 'Project name is required' });
        return;
      }
      if (project.archived) {
        sendJson(response, 409, { error: 'Archived projects cannot be renamed' });
        return;
      }
      renameProject.run(name, projectId);
      sendJson(response, 200, { ...project, name });
      return;
    }
    sendJson(response, 200, project);
    return;
  }

  const tasksMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks$/);
  if (tasksMatch) {
    const projectId = decodeURIComponent(tasksMatch[1]);
    if (!getProject.get(projectId)) {
      sendJson(response, 404, { error: 'Project not found' });
      return;
    }
    if (request.method === 'GET') {
      sendJson(response, 200, listTasks.all(projectId));
      return;
    }
    if (request.method === 'POST') {
      const body = await readJson(request);
      const title = typeof body?.title === 'string' ? body.title.trim() : '';
      if (!title) {
        sendJson(response, 400, { error: 'Task title is required' });
        return;
      }
      const task = { id: randomUUID(), projectId, title, completed: 0 };
      insertTask.run(task.id, projectId, title, Date.now());
      sendJson(response, 201, task);
      return;
    }
  }

  const taskMatch = url.pathname.match(/^\/api\/projects\/([^/]+)\/tasks\/([^/]+)$/);
  if (taskMatch && request.method === 'PATCH') {
    const projectId = decodeURIComponent(taskMatch[1]);
    const taskId = decodeURIComponent(taskMatch[2]);
    const existing = getTask.get(taskId, projectId);
    if (!existing) {
      sendJson(response, 404, { error: 'Task not found' });
      return;
    }
    const body = await readJson(request);
    if (typeof body?.completed !== 'boolean') {
      sendJson(response, 400, { error: 'Task completion must be a boolean' });
      return;
    }
    updateTask.run(body.completed ? 1 : 0, taskId, projectId);
    sendJson(response, 200, { ...existing, completed: body.completed ? 1 : 0 });
    return;
  }

  if (request.method !== 'GET') {
    sendJson(response, 404, { error: 'Not found' });
    return;
  }
  const filePath = url.pathname === '/' || url.pathname.startsWith('/projects/')
    ? join(publicDirectory, 'index.html')
    : join(publicDirectory, url.pathname.replace(/^\//, ''));
  if (!filePath.startsWith(publicDirectory)) {
    response.writeHead(404).end();
    return;
  }
  try {
    const content = await readFile(filePath);
    const type = extname(filePath) === '.js' ? 'text/javascript; charset=utf-8' : 'text/html; charset=utf-8';
    response.writeHead(200, { 'content-type': type });
    response.end(content);
  } catch {
    response.writeHead(404).end('Not found');
  }
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');
const app = document.querySelector('#app');

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  for (const [name, value] of Object.entries(attributes)) node.setAttribute(name, value);
  return node;
}

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Something went wrong');
  return data;
}

async function renderProjects() {
  app.replaceChildren(element('h1', 'Workboard'));
  const filterLabel = element('label', 'Project filter', { for: 'project-filter' });
  const filter = element('select', undefined, { id: 'project-filter', 'aria-label': 'Project filter' });
  for (const value of ['Active', 'Archived']) filter.append(element('option', value, { value }));
  app.append(filterLabel, filter);
  const form = element('form');
  const label = element('label', 'Project name', { for: 'project-name' });
  const input = element('input', undefined, { id: 'project-name', name: 'name', type: 'text', 'aria-label': 'Project name' });
  const submit = element('button', 'Create project', { type: 'submit' });
  const alert = element('p', undefined, { role: 'alert', hidden: '' });
  form.append(label, input, submit);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.hidden = true;
    try {
      const project = await request('/api/projects', {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ name: input.value }),
      });
      input.value = '';
      await loadProjects();
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
    }
  });

  const list = element('ul');
  async function loadProjects() {
    const projects = await request(`/api/projects?filter=${filter.value}`);
    list.replaceChildren();
    for (const project of projects) {
      const row = element('li', undefined, { 'data-testid': 'project-row' });
      const name = element('span', project.name, { class: 'project-name' });
      const summary = element('span', `${project.completedCount || 0}/${project.totalCount} completed`, { 'data-testid': 'project-summary' });
      const open = element('button', 'Open project', { type: 'button' });
      open.addEventListener('click', () => {
        window.location.href = `/projects/${encodeURIComponent(project.id)}`;
      });
      const archive = element('button', filter.value === 'Active' ? 'Archive project' : 'Restore project', { type: 'button' });
      archive.addEventListener('click', async () => {
        try {
          await request(`/api/projects/${encodeURIComponent(project.id)}/archive`, {
            method: 'PATCH', headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ archived: filter.value === 'Active' }),
          });
          await loadProjects();
        } catch (error) { alert.textContent = error.message; alert.hidden = false; }
      });
      row.append(name, summary, open, archive);
      list.append(row);
    }
  }
  filter.addEventListener('change', loadProjects);
  app.append(form, alert, list);
  await loadProjects();
}

async function renderProject(id) {
  app.replaceChildren();
  try {
    const project = await request(`/api/projects/${encodeURIComponent(id)}`);
    const back = element('button', 'Projects', { type: 'button', class: 'back' });
    back.addEventListener('click', () => { window.location.href = '/'; });
    app.append(back, element('h1', project.name));
    const archived = Boolean(project.archived);
    if (archived) app.append(element('p', 'Archived project'));

    const alert = element('p', undefined, { role: 'alert', hidden: '' });
    const renameForm = element('form');
    const renameLabel = element('label', 'New project name', { for: 'new-project-name' });
    const renameInput = element('input', undefined, {
      id: 'new-project-name', name: 'name', type: 'text', 'aria-label': 'New project name',
    });
    const renameButton = element('button', 'Rename project', { type: 'submit' });
    renameInput.disabled = archived;
    renameButton.disabled = archived;
    renameForm.append(renameLabel, renameInput, renameButton);
    renameForm.addEventListener('submit', async (event) => {
      event.preventDefault();
      alert.hidden = true;
      try {
        const updated = await request(`/api/projects/${encodeURIComponent(id)}`, {
          method: 'PATCH',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ name: renameInput.value }),
        });
        app.querySelector('h1').textContent = updated.name;
        renameInput.value = '';
      } catch (error) {
        alert.textContent = error.message;
        alert.hidden = false;
      }
    });

    const form = element('form');
    const label = element('label', 'Task title', { for: 'task-title' });
    const input = element('input', undefined, { id: 'task-title', name: 'title', type: 'text', 'aria-label': 'Task title' });
    const submit = element('button', 'Create task', { type: 'submit' });
    submit.disabled = archived;
    form.append(label, input, submit);

    const filterLabel = element('label', 'Task filter', { for: 'task-filter' });
    const filter = element('select', undefined, { id: 'task-filter', 'aria-label': 'Task filter' });
    for (const value of ['All', 'Open', 'Completed']) filter.append(element('option', value, { value }));
    const list = element('ul');
    let tasks = await request(`/api/projects/${encodeURIComponent(id)}/tasks`);
    const renderTasks = () => {
      const matching = tasks.filter((task) => filter.value === 'All'
        || (filter.value === 'Completed' ? Boolean(task.completed) : !task.completed));
      list.replaceChildren();
      for (const task of matching) {
        const row = element('li', undefined, { 'data-testid': 'task-row' });
        const checkbox = element('input', undefined, {
          type: 'checkbox',
          'aria-label': `Complete ${task.title}`,
        });
        checkbox.checked = Boolean(task.completed);
        checkbox.disabled = archived;
        checkbox.addEventListener('change', async () => {
          checkbox.disabled = true;
          try {
            const updated = await request(`/api/projects/${encodeURIComponent(id)}/tasks/${encodeURIComponent(task.id)}`, {
              method: 'PATCH',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ completed: checkbox.checked }),
            });
            task.completed = updated.completed;
            renderTasks();
          } catch (error) {
            checkbox.checked = Boolean(task.completed);
            alert.textContent = error.message;
            alert.hidden = false;
          } finally {
            checkbox.disabled = false;
          }
        });
        row.append(element('span', task.title), checkbox);
        list.append(row);
      }
    };
    filter.addEventListener('change', renderTasks);
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      alert.hidden = true;
      try {
        const task = await request(`/api/projects/${encodeURIComponent(id)}/tasks`, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ title: input.value }),
        });
        tasks.push(task);
        input.value = '';
        renderTasks();
      } catch (error) {
        alert.textContent = error.message;
        alert.hidden = false;
      }
    });
    renderTasks();
    app.append(renameForm, alert, form, filterLabel, filter, list);
  } catch {
    app.append(element('h1', 'Project not found'));
    const back = element('button', 'Projects', { type: 'button' });
    back.addEventListener('click', () => { window.location.href = '/'; });
    app.append(back);
  }
}

const match = window.location.pathname.match(/^\/projects\/([^/]+)\/?$/);
if (match) renderProject(decodeURIComponent(match[1]));
else renderProjects().catch(() => {
  app.replaceChildren(element('h1', 'Workboard'), element('p', 'Unable to load projects.'));
});
